def default_transcript_dir() -> Path | None:
    # Cursor stores transcripts under ~/.cursor/projects/<slug>/agent-transcripts
    # Use environment variable or scan for available project directories
    env_path = os.environ.get("CURSOR_TRANSCRIPT_DIR")
    if env_path:
        return Path(env_path)
    cursor_projects = Path.home() / ".cursor" / "projects"
    if cursor_projects.is_dir():
        projects = [p for p in cursor_projects.iterdir() if p.is_dir()]
        if projects:
            # Use the most recently modified project directory
            latest = max(projects, key=lambda p: p.stat().st_mtime)
            return latest / "agent-transcripts"
    return None

if len(sys.argv) > 1:
    base = Path(sys.argv[1])
else:
    base = default_transcript_dir()
