await transaction(async (client) => {
  // First, verify all rows belong to this employer in one query
  const validIds = rowsIn
    .map(r => String(r?.id || '').trim())
    .filter(id => id && isUuid(id));

  if (validIds.length === 0) return;

  const ownCheck = await client.query(
    `SELECT ear.id
     FROM employer_assessment_rows ear
     JOIN employer_assessment_uploads u ON u.id = ear.upload_id
     WHERE ear.id = ANY($1::uuid[]) AND ear.upload_id = $2::uuid AND u.employer_id = $3::uuid`,
    [validIds, uploadId, employerId],
  );

  const ownedIds = new Set(ownCheck.rows.map(r => r.id));

  // Build bulk update using a VALUES table
  const values = [];
  const params = [];
  let paramIndex = 1;

  for (const r of rowsIn) {
    const rowId = String(r?.id || '').trim();
    if (!rowId || !isUuid(rowId) || !ownedIds.has(rowId)) continue;

    values.push(`($${paramIndex}::uuid, $${paramIndex+1}, $${paramIndex+2}, $${paramIndex+3}, $${paramIndex+4}, $${paramIndex+5}, $${paramIndex+6}, $${paramIndex+7})`);
