export async function GET(request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user || session.user.role !== 'employer') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }
    const employerId = await getEmployerId(session);
    if (!employerId) {
      return NextResponse.json({ drives: [], students: [] });
    }

    const { searchParams } = new URL(request.url);
    const driveLimit = Math.min(parseInt(searchParams.get('driveLimit') || '100', 10), 300);
    const studentLimit = Math.min(parseInt(searchParams.get('studentLimit') || '100', 10), 500);
    const driveOffset = Math.max(parseInt(searchParams.get('driveOffset') || '0', 10), 0);
    const studentOffset = Math.max(parseInt(searchParams.get('studentOffset') || '0', 10), 0);

    const [drivesRes, studentsRes] = await Promise.all([
      query(
        `SELECT id, title, drive_date
         FROM placement_drives
         WHERE employer_id = $1
         ORDER BY drive_date DESC, created_at DESC
         LIMIT $2 OFFSET $3`,
        [employerId, driveLimit, driveOffset]
      ),
      query(
        `SELECT sp.id, u.first_name, u.last_name, u.email, t.name AS college_name
         FROM applications a
         JOIN placement_drives d ON d.id = a.drive_id
         JOIN student_profiles sp ON sp.id = a.student_id
         JOIN users u ON u.id = sp.user_id
         LEFT JOIN tenants t ON t.id = sp.tenant_id
         WHERE d.employer_id = $1
         ORDER BY u.first_name ASC, u.last_name ASC
         LIMIT $2 OFFSET $3`,
        [employerId, studentLimit, studentOffset]
      ),
    ]);

    return NextResponse.json({
      drives: drivesRes.rows,
      students: studentsRes.rows.map((s) => ({
        id: s.id,
        name: `${s.first_name || ''} ${s.last_name || ''}`.trim() || s.email || 'Unknown Student',
        email: s.email,
        collegeName: s.college_name || '',
      })),
    });
  } catch (error) {
    console.error('Failed to load offer options:', error);
    return NextResponse.json({ error: 'Failed to load options' }, { status: 500 });
  }
}

