function formatSalary(min, max) {
  if (!min && !max) return 'Not disclosed';
  if (min && max) return `₹${(min / 100000).toFixed(1)}L - ₹${(max / 100000).toFixed(1)}L PA`;
  if (min) return `₹${(min / 100000).toFixed(1)}L+ PA`;
  return `Up to ₹${(max / 100000).toFixed(1)}L PA`;
}

issues.fixed_snippet:
function formatSalary(min, max, currency = 'INR') {
  if ((!min || min === 0) && (!max || max === 0)) return 'Not disclosed';
  const symbol = currency === 'USD' ? '$' : '₹';
  const divisor = currency === 'USD' ? 1000 : 100000;
  const suffix = currency === 'USD' ? 'K' : 'L';
  if (min && max) return `${symbol}${(min / divisor).toFixed(1)}${suffix} - ${symbol}${(max / divisor).toFixed(1)}${suffix} PA`;
  if (min) return `${symbol}${(min / divisor).toFixed(1)}${suffix}+ PA`;
  return `Up to ${symbol}${(max / divisor).toFixed(1)}${suffix} PA`;
}

