import logger from '@/lib/logger'; // assuming a structured logger exists

export function getSessionTenantId(user) {
  if (!user) {
    logger.warn('getSessionTenantId called with null user');
    return null;
  }
  const id = user.tenantId ?? user.tenant_id ?? null;
  const trimmed = id && String(id).trim() ? String(id).trim() : null;
  if (!trimmed) {
    logger.warn('No tenant ID found in user session', { userId: user.id });
  }
  return trimmed;
}

